-- Tình huống (phần 2)
INSERT INTO public.scenarios (category_id, title, title_zh, description, situation, learning_objectives, difficulty, estimated_minutes, ai_role, ai_role_zh, ai_personality, initial_message, suggested_phrases, is_published)
SELECT c.id, s.title, s.title_zh, s.description, s.situation, s.obj, s.diff, s.mins, s.ai_role, s.ai_role_zh, s.pers, s.init, s.phr::jsonb, TRUE
FROM (VALUES
($q$Công nghệ thông tin$q$, $q$Chào hỏi và nhờ hỗ trợ cài đặt môi trường lập trình$q$, $q$请教配置开发环境$q$, $q$Thực hành giao tiếp cơ bản với người hướng dẫn để xin cấp quyền tài khoản và nhờ hỗ trợ cài đặt môi trường làm việc ngày đầu tiên.$q$, $q$Bạn vừa nhận máy tính làm việc trong ngày đầu thực tập tại công ty IT Trung Quốc. Bạn cần chào hỏi anh hướng dẫn (mentor) và nhờ anh ấy cấp quyền truy cập Git cũng như hỗ trợ cài đặt môi trường phát triển ứng dụng.$q$, ARRAY[$q$Biết cách chào hỏi lịch sự và giới thiệu bản thân trong môi trường doanh nghiệp IT.$q$,$q$Sử dụng các từ vựng cơ bản về thiết bị, tài khoản và công cụ lập trình.$q$,$q$Hỏi xin sự trợ giúp khi gặp khó khăn kỹ thuật ban đầu.$q$]::text[], $q$beginner$q$, 10, $q$Lập trình viên lâu năm / Mentor hướng dẫn$q$, $q$导师 / 资深开发人员$q$, $q$Thân thiện, kiên nhẫn và sẵn sàng giúp đỡ thực tập sinh mới.$q$, $q$你好！我是你的带教导师李伟。电脑和账号都拿到了吗？配置环境有没有遇到问题？$q$, $q$[{"zh":"李老师好，请问 me 可以申请一下 Git 代码库的权限吗？","vi":"Chào thầy/anh Lý, em có thể xin cấp quyền vào kho mã nguồn Git được không ạ?"},{"zh":"我的开发环境报错了，能帮我看一眼吗？","vi":"Môi trường phát triển của em bị báo lỗi, anh xem giúp em một chút được không?"},{"zh":"我已经安装好软件了，接下来做什么？","vi":"Em đã cài xong phần mềm rồi, tiếp theo em nên làm gì ạ?"},{"zh":"非常感谢您的指导！","vi":"Rất cảm ơn sự hướng dẫn của anh!"}]$q$),
($q$Công nghệ thông tin$q$, $q$Báo cáo tiến độ sửa lỗi và xin gia hạn thời gian bàn giao$q$, $q$汇报Bug修复进度$q$, $q$Giao tiếp với Trưởng nhóm (Tech Lead) để giải thích nguyên nhân phát sinh lỗi phức tạp và đề xuất lùi thời gian nộp code.$q$, $q$Bạn đang chịu trách nhiệm sửa một lỗi hệ thống liên quan đến luồng thanh toán. Tuy nhiên, do mã nguồn cũ khá phức tạp và phát sinh lỗi cơ sở dữ liệu nên bạn không thể hoàn thành đúng 5h chiều nay như cam kết.$q$, ARRAY[$q$Trình bày rõ ràng nguyên nhân kỹ thuật gây trễ tiến độ công việc.$q$,$q$Sử dụng thành thạo thuật ngữ CNTT phổ biến (Bug, Database, Deadlock, Refactor).$q$,$q$Đề xuất giải pháp khắc phục và mốc thời gian hoàn thành mới một cách chuyên nghiệp.$q$]::text[], $q$intermediate$q$, 15, $q$Trưởng nhóm dự án (Tech Lead)$q$, $q$项目组长 (Tech Lead)$q$, $q$Nghiêm túc, chú trọng hiệu quả công việc nhưng lý trí và biết lắng nghe.$q$, $q$小王，下午好。支付模块那个紧急 Bug 修复得怎么样了？今天下班前能上线吗？$q$, $q$[{"zh":"组长，我在排查过程中发现是数据库死锁导致的。","vi":"Tổ trưởng, trong quá trình rà soát em phát hiện nguyên nhân là do khóa chết cơ sở dữ liệu (deadlock)."},{"zh":"因为涉及旧代码重构，估计需要多花两个小时。","vi":"Vì liên quan đến tái cấu trúc mã nguồn cũ, ước tính cần tốn thêm khoảng 2 tiếng nữa."},{"zh":"我会在今晚八点前完成测试并提交代码。","vi":"Em sẽ hoàn thành kiểm thử và push code trước 8 giờ tối nay."},{"zh":"非常抱歉耽误了项目进度，我会尽快解决。","vi":"Rất xin lỗi vì làm chậm tiến độ dự án, em sẽ giải quyết sớm nhất có thể."}]$q$),
($q$Công nghệ thông tin$q$, $q$Trao đổi với khách hàng về cải thiện giao diện phần mềm$q$, $q$与客户确认UI界面需求$q$, $q$Làm việc với đại diện phía khách hàng để làm rõ phản hồi trải nghiệm người dùng và thống nhất phương án điều chỉnh giao diện.$q$, $q$Khách hàng phản hồi rằng bản dùng thử của ứng dụng di động có giao diện trang chủ khá rối và hình ảnh load chậm. Bạn tham gia buổi họp trực tuyến với đại diện khách hàng để ghi nhận góp ý và giải thích giải pháp kỹ thuật tối ưu.$q$, ARRAY[$q$Biết lắng nghe và ghi nhận phản hồi (feedback) từ khách hàng bằng tiếng Trung.$q$,$q$Giải thích các khái niệm UI/UX và tối ưu hóa hiệu năng bằng ngôn ngữ dễ hiểu.$q$,$q$Thể hiện thái độ cầu thị, lịch sự và tác phong dịch vụ khách hàng chuẩn mực.$q$]::text[], $q$intermediate$q$, 15, $q$Đại diện Quản lý Sản phẩm phía Khách hàng$q$, $q$客户方产品经理$q$, $q$Yêu cầu cao, thẳng thắn nhưng cởi mở nếu nghe được giải pháp hợp lý.$q$, $q$你好！我们体验了新版的 App，感觉首页排版太拥挤了，而且图片加载速度也慢。$q$, $q$[{"zh":"您好，感谢您的反馈！能具体说一下是哪些图片加载偏慢吗？","vi":"Xin chào, cảm ơn phản hồi của anh/chị! Anh/chị có thể nói rõ hơn là những hình ảnh nào bị tải chậm không ạ?"},{"zh":"针对移动端，我们建议采用折叠布局和图片懒加载技术。","vi":"Đối với bản di động, chúng em đề xuất sử dụng bố cục thu gọn và kỹ thuật lazy-loading cho hình ảnh."},{"zh":"我们会在本周五前给出修改后的原型图供您确认。","vi":"Chúng em sẽ gửi bản prototype đã chỉnh sửa trước thứ Sáu tuần này để anh/chị xác nhận."},{"zh":"请问除了首页排版，还有其他需要调整的地方吗？","vi":"Cho em hỏi ngoài bố cục trang chủ ra thì còn chỗ nào cần điều chỉnh nữa không ạ?"}]$q$),
($q$Công nghệ thông tin$q$, $q$Thương lượng phương án tích hợp API và bảo mật với đối tác$q$, $q$对接第三方API与安全协议$q$, $q$Thảo luận kỹ thuật chuyên sâu với Kiến trúc sư hệ thống của công ty đối tác để thống nhất chuẩn xác thực Token và giới hạn băng thông.$q$, $q$Công ty bạn đang tích hợp cổng thanh toán của một đối tác tài chính lớn. Bạn đại diện cho nhóm phát triển tham gia buổi họp kỹ thuật với Kỹ sư trưởng phía đối tác để chốt phương án bảo mật OAuth2.0 và xử lý sự cố khi lưu lượng truy cập tăng vọt.$q$, ARRAY[$q$Sử dụng thành thạo từ vựng chuyên ngành CNTT nâng cao (OAuth2.0, Token, Encryption, QPS, Rate Limit).$q$,$q$Đàm phán và thống nhất tiêu chuẩn kỹ thuật giữa hai hệ thống của hai doanh nghiệp.$q$,$q$Bảo vệ quan điểm kỹ thuật của đội nhà nhưng vẫn giữ được mối quan hệ hợp tác tôn trọng.$q$]::text[], $q$advanced$q$, 20, $q$Kiến trúc sư hệ thống phía Đối tác$q$, $q$第三方合作方系统架构师$q$, $q$Cực kỳ chuyên nghiệp, khắt khe về mặt bảo mật và hiệu năng, thích làm việc theo quy chuẩn kỹ thuật nghiêm ngặt.$q$, $q$你好，关于这次支付网关的对接，出于安全考虑，我们要求所有请求必须经过双向签名加 Token 校验，且 QPS 限制在 500 以内。$q$, $q$[{"zh":"关于高并发场景下的 QPS 限制，500 可能无法满足我们促销期间的峰值需求。","vi":"Về giới hạn QPS trong kịch bản truy cập cao, mức 500 có thể không đáp ứng được nhu cầu đỉnh điểm đợt khuyến mãi của chúng tôi."},{"zh":"我们建议采用 OAuth2.0 进行身份验证，并使用 AES-256 加密传输数据。","vi":"Chúng tôi đề xuất sử dụng OAuth2.0 để xác thực danh tính và dùng mã hóa AES-256 cho dữ liệu truyền đi."},{"zh":"如果接口出现超时，贵方是否有自动重试机制和降级方案？","vi":"Nếu API bị timeout, quý công ty có cơ chế tự động thử lại và phương án hạ cấp (degradation) không?"},{"zh":"我们可以先在测试环境进行联调，确认数据格式无误后再上线。","vi":"Chúng ta có thể tiến hành tích hợp liên thông trên môi trường test trước, xác nhận định dạng dữ liệu không sai sót mới cho lên production."}]$q$),
($q$Công nghệ thông tin$q$, $q$Hỏi đồng nghiệp về quy trình Code Review và gửi Pull Request$q$, $q$请教代码审查流程$q$, $q$Thực tập sinh chủ động xin hướng dẫn từ đồng nghiệp về quy trình kiểm tra mã nguồn trước khi đẩy lên hệ thống.$q$, $q$Bạn vừa hoàn thành nhiệm vụ lập trình đầu tiên và cần đưa mã nguồn vào nhánh chính của dự án. Bạn đến gặp đồng nghiệp phụ trách hướng dẫn để hỏi về quy trình Code Review và cách tạo Pull Request đúng quy định của công ty.$q$, ARRAY[$q$Học cách hỏi và tiếp nhận hướng dẫn về quy trình làm việc kỹ thuật$q$,$q$Nắm vững thuật ngữ tiếng Trung liên quan đến quản lý mã nguồn (Git, Branch, Code Review)$q$,$q$Rèn luyện kỹ năng giao tiếp lịch sự, chủ động trong môi trường làm việc nhóm$q$]::text[], $q$beginner$q$, 10, $q$Đồng nghiệp hướng dẫn (Senior Developer)$q$, $q$资深开发人员$q$, $q$Thân thiện, kiên nhẫn và sẵn sàng chia sẻ kinh nghiệm cho người mới.$q$, $q$你好！听说你第一个功能模块已经写好了，遇到什么问题需要我帮忙吗？$q$, $q$[{"zh":"请问我们团队的代码审查流程是怎样的？","vi":"Cho mình hỏi quy trình review code của team mình như thế nào?"},{"zh":"我需要把代码提交到哪一个分支？","vi":"Tôi cần push code vào nhánh nào vậy?"},{"zh":"请帮我看一下这个 Pull Request 没问题吧？","vi":"Nhờ anh/chị xem giúp em Pull Request này có vấn đề gì không?"},{"zh":"谢谢，我会按照你的建议修改。自由","vi":"Cảm ơn, tôi sẽ sửa theo góp ý của bạn."}]$q$),
($q$Công nghệ thông tin$q$, $q$Báo cáo sự cố máy chủ thử nghiệm với Trưởng nhóm kỹ thuật$q$, $q$向技术组长汇报测试服务器故障$q$, $q$Thực tập sinh giải trình nguyên nhân máy chủ thử nghiệm bị gián đoạn và đề xuất giải pháp xử lý với cấp trên.$q$, $q$Trong lúc thử nghiệm tính năng mới, máy chủ thử nghiệm (Test Server) bất ngờ bị sập làm ảnh hưởng đến các thành viên khác. Bạn cần khẩn trương báo cáo với Trưởng nhóm kỹ thuật về nguyên nhân sự cố và đưa ra hướng khắc phục ngay lập tức.$q$, ARRAY[$q$Nắm vững cấu trúc câu báo cáo sự cố kỹ thuật khẩn cấp bằng tiếng Trung$q$,$q$Rèn luyện phản xạ trình bày nguyên nhân và phương án giải quyết (Troubleshooting)$q$,$q$Thể hiện thái độ làm việc có trách nhiệm và bình tĩnh trước cấp trên$q$]::text[], $q$intermediate$q$, 15, $q$Trưởng nhóm kỹ thuật (Tech Lead)$q$, $q$技术组长$q$, $q$Nghiêm túc, chú trọng hiệu quả công việc và yêu cầu báo cáo rõ ràng, chính xác.$q$, $q$怎么回事？测试服务器刚才突然连不上了，你那边刚才在跑什么程序？$q$, $q$[{"zh":"组长，测试服务器刚才因为内存溢出崩掉了。","vi":"Thưa trưởng nhóm, server test vừa sập do tràn bộ nhớ."},{"zh":"我在测试大量数据并发导入时发现了这个问题。","vi":"Tôi phát hiện ra vấn đề này khi test nhập dữ liệu đồng thời số lượng lớn."},{"zh":"我正在重启服务并清理缓存，预计十五分钟内恢复。","vi":"Tôi đang khởi động lại service và dọn dẹp cache, dự kiến khôi phục trong 15 phút."},{"zh":"以后我会先在本地环境做好压力测试。","vi":"Sau này em sẽ làm stress test trên môi trường local trước."}]$q$),
($q$Công nghệ thông tin$q$, $q$Thống nhất kế hoạch kiểm thử tải hệ thống với đối tác hạ tầng Cloud$q$, $q$与云服务供应商对接压力测试计划$q$, $q$Thực tập sinh làm việc với bên cung cấp dịch vụ Cloud để chốt thời gian và thông số kiểm thử tải cho hệ thống.$q$, $q$Công ty bạn chuẩn bị ra mắt sản phẩm mới và cần phối hợp với đối tác cung cấp máy chủ Cloud để triển khai bài kiểm thử chịu tải (Stress Test). Bạn chịu trách nhiệm liên lạc với chuyên viên kỹ thuật của đối tác để trao đổi thời gian, quy mô băng thông và các kịch bản thử nghiệm.$q$, ARRAY[$q$Sử dụng thành thạo từ vựng tiếng Trung chuyên ngành hạ tầng mạng và điện toán đám mây$q$,$q$Rèn luyện kỹ năng trao đổi công việc chuyên nghiệp với đối tác bên ngoài$q$,$q$Biết cách làm rõ các thông số kỹ thuật và đạt được thỏa thuận chung$q$]::text[], $q$intermediate$q$, 15, $q$Chuyên viên kỹ thuật phía đối tác Cloud$q$, $q$云服务商技术支持工程师$q$, $q$Chuyên nghiệp, lịch sự, chú trọng chi tiết thông số kỹ thuật.$q$, $q$你好，我是云服务团队的张工。收到你们关于进行全链路压力测试的申请，请问具体计划怎么安排？$q$, $q$[{"zh":"我们计划在明天晚上十点开始压力测试。","vi":"Chúng tôi dự kiến bắt đầu kiểm thử tải vào 10 giờ tối mai."},{"zh":"预计峰值并发量会达到每秒一万次请求。","vi":"Dự kiến lượng truy cập đồng thời đỉnh điểm đạt 10.000 request/giây."},{"zh":"请问在此期间需要我们临时提升服务器带宽吗？","vi":"Cho hỏi trong thời gian này có cần chúng tôi tạm thời nâng băng thông server không?"},{"zh":"测试结束后，我们会把详细报告发给您。","vi":"Sau khi test xong, chúng tôi sẽ gửi báo cáo chi tiết cho anh."}]$q$),
($q$Công nghệ thông tin$q$, $q$Thương lượng với khách hàng về thay đổi yêu cầu tính năng ngoài phạm vi dự án$q$, $q$与客户沟通需求变更与项目范围$q$, $q$Thực tập sinh khéo léo từ chối hoặc hoãn yêu cầu tính năng phát sinh ngoài hợp đồng của khách hàng mà vẫn duy trì quan hệ tốt.$q$, $q$Trong cuộc họp rà soát sản phẩm, đại diện khách hàng bất ngờ yêu cầu bổ sung thêm một tính năng phân tích dữ liệu phức tạp ngay trong đợt bàn giao tới. Bạn cần trao đổi với khách hàng, giải thích rằng yêu cầu này nằm ngoài phạm vi (Scope) hợp đồng ban đầu và thuyết phục họ dời tính năng này sang giai đoạn 2.$q$, ARRAY[$q$Nắm vững kỹ năng đàm phán và xử lý tình huống phát sinh yêu cầu (Scope Creep) bằng tiếng Trung$q$,$q$Sử dụng ngôn ngữ khéo léo, kiên định nhưng vẫn giữ thái độ tôn trọng khách hàng$q$,$q$Học cách đưa ra phương án thay thế hợp lý để bảo vệ tiến độ dự án$q$]::text[], $q$advanced$q$, 20, $q$Đại diện phía khách hàng (Product Owner)$q$, $q$客户方项目负责人$q$, $q$Kỳ vọng cao, hơi cứng rắn và luôn muốn đòi hỏi thêm tính năng tốt nhất cho sản phẩm.$q$, $q$这个版本的演示效果不错，不过我们希望在下周上线前，再加上一个自定义数据报表导出功能。$q$, $q$[{"zh":"这个需求超出了我们最初确定的项目范围。","vi":"Yêu cầu này vượt quá phạm vi dự án đã xác định ban đầu của chúng ta."},{"zh":"如果现在新增这个功能，可能会导致项目延期交付。","vi":"Nếu thêm tính năng này ngay bây giờ có thể dẫn đến việc bàn giao dự án bị chậm trễ."},{"zh":"建议将这个功能作为第二期的优化需求来开发。","vi":"Đề xuất đưa tính năng này vào phát triển như một yêu cầu tối ưu ở giai đoạn 2."},{"zh":"我们会在今天内评估好第二期的工时和成本发给您。","vi":"Chúng tôi sẽ đánh giá thời gian và chi phí cho giai đoạn 2 rồi gửi anh/chị trong hôm nay."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Hướng dẫn quy trình nộp hóa đơn thanh toán nội bộ$q$, $q$请教报销流程$q$, $q$Thực hành hỏi đồng nghiệp tiền bối về cách phân loại và dán hóa đơn chứng từ đúng quy định công ty.$q$, $q$Bạn là thực tập sinh mới tại phòng kế toán của một công ty Trung Quốc. Bạn cần hỏi chị Trương (kế toán viên tiền bối) cách phân loại hóa đơn và điền phiếu thanh toán chi phí (报销单) cho chuyến công tác tuần trước của phòng.$q$, ARRAY[$q$Nắm vững từ vựng cơ bản về chứng từ thanh toán và hóa đơn (报销单, 发票, 凭证)$q$,$q$Biết cách sử dụng các câu hỏi lịch sự khi xin hướng dẫn từ đồng nghiệp đi trước$q$,$q$Hiểu quy tắc kiểm tra tính hợp lệ của hóa đơn tài chính trong công ty Trung Quốc$q$]::text[], $q$beginner$q$, 10, $q$Chị Trương - Kế toán viên tiền bối$q$, $q$张姐 - 资深会计$q$, $q$Thân thiện, nhiệt tình nhưng rất cẩn thận và tỉ mỉ trong công việc.$q$, $q$小阮，你拿着出差的那些发票过来了吧？把报销单拿给我看看，我教你怎么整理。$q$, $q$[{"zh":"张姐，请问差旅费报销单要怎么填写？","vi":"Chị Trương, cho em hỏi phiếu thanh toán chi phí công tác điền như thế nào ạ?"},{"zh":"这些发票需要按日期分类黏贴吗？","vi":"Những hóa đơn này có cần dán phân loại theo ngày không ạ?"},{"zh":"增值税专用发票和普通发票要分开吗？","vi":"Hóa đơn GTGT chuyên dùng và hóa đơn thông thường có phải tách riêng ra không?"},{"zh":"谢谢张姐，我这就去重新整理一下。","vi":"Cảm ơn chị Trương, em sẽ đi sắp xếp lại ngay ạ."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Báo cáo tiến độ đối chiếu công nợ tháng với Kế toán trưởng$q$, $q$汇报月度对账进度$q$, $q$Thực hành báo cáo tình hình đối chiếu sổ sách công nợ và giải trình chênh lệch số liệu với cấp trên.$q$, $q$Bạn đang hoàn thành công tác đối chiếu công nợ tháng với các nhà cung cấp. Bạn cần vào văn phòng báo cáo với Trưởng phòng Kế toán (Anh Lý) về tiến độ và giải thích nguyên nhân chênh lệch số liệu với một nhà cung cấp lớn.$q$, ARRAY[$q$Sử dụng thành thạo từ vựng về công nợ và đối chiếu sổ sách (应付款, 对账单, 差额)$q$,$q$Rèn luyện kỹ năng báo cáo công việc ngắn gọn, rõ ràng với cấp trên$q$,$q$Biết cách đề xuất giải pháp xử lý sai lệch số liệu trong kế toán$q$]::text[], $q$intermediate$q$, 15, $q$Anh Lý - Trưởng phòng Kế toán$q$, $q$李经理 - 财务主管$q$, $q$Nghiêm túc, coi trọng hiệu suất và đòi hỏi sự chính xác tuyệt đối về số liệu.$q$, $q$小阮，请进。供应商A公司的月度对账搞定了吗？听说金额有点出入？$q$, $q$[{"zh":"李经理，这是本月的对账汇总表，请您过目。","vi":"Trưởng phòng Lý, đây là bảng tổng hợp đối chiếu công nợ tháng này, mời anh xem qua."},{"zh":"经过核对，我们与A公司的账面金额存在五千元的差额。","vi":"Qua đối chiếu, số tiền trên sổ sách của chúng ta và công ty A có chênh lệch 5.000 tệ."},{"zh":"原因是一笔在途货物尚未入库，导致记账时间不一致。","vi":"Nguyên nhân là do một lô hàng đang trên đường vận chuyển chưa nhập kho, dẫn đến thời gian ghi sổ không nhất quán."},{"zh":"我会跟进催促对方补齐单据，预计明天更正完毕。","vi":"Em sẽ theo dõi đôn đốc bên kia bổ sung chứng từ, dự kiến ngày mai sẽ điều chỉnh xong."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Giải đáp thắc mắc của đối tác về hóa đơn và điều khoản thanh toán$q$, $q$解答客户发票与付款疑问$q$, $q$Thực hành giao tiếp với khách hàng doanh nghiệp để giải thích thông tin trên hóa đơn GTGT và thời hạn thanh toán.$q$, $q$Khách hàng gọi điện tới phòng kế toán thắc mắc về mức thuế suất và thông tin ngân hàng trên hóa đơn vừa nhận được. Bạn đại diện phòng kế toán lắng nghe, giải đáp thắc mắc và hướng dẫn họ thủ tục thanh toán đúng hạn.$q$, ARRAY[$q$Sử dụng ngữ khí lịch sự, chuyên nghiệp khi trao đổi với khách hàng bên ngoài$q$,$q$Nắm vững các khái niệm thuế GTGT, tài khoản ngân hàng và điều khoản hợp đồng (税率, 账号, 付款期限)$q$,$q$Giải quyết khiếu nại hoặc thắc mắc về chứng từ một cách thỏa đáng$q$]::text[], $q$intermediate$q$, 15, $q$Anh Vương - Đại diện Bộ phận Thu mua của Khách hàng$q$, $q$王经理 - 客户采购代表$q$, $q$Thẳng thắn, hơi nóng tính nhưng lý trí và coi trọng sự hợp tác.$q$, $q$你好，我是B公司的王经理。我们刚收到你们寄来的电子发票，为什么税率是13%？我们合同里写的不是包含服务费吗？$q$, $q$[{"zh":"王经理您好，请您先别着急，我帮您核对一下合同条款。","vi":"Chào anh Vương, anh đừng vội, em sẽ giúp anh đối chiếu lại điều khoản hợp đồng."},{"zh":"根据最新的税收政策，该类产品的增值税税率为13%。","vi":"Theo chính sách thuế mới nhất, thuế suất thuế GTGT của loại sản phẩm này là 13%."},{"zh":"如果发票信息有误，我们可以为您开具红字发票进行冲销。","vi":"Nếu thông tin hóa đơn có sai sót, chúng em có thể xuất hóa đơn điều chỉnh giảm (hóa đơn đỏ) để gạch nợ."},{"zh":"请问您方便把收到的发票截图发给我确认一下吗？","vi":"Cho hỏi anh có tiện chụp màn hình hóa đơn đã nhận gửi cho em xác nhận không ạ?"}]$q$),
($q$Tài chính - Kế toán$q$, $q$Giải trình số liệu trích lập dự phòng với Đơn vị Kiểm toán$q$, $q$配合外部审计解答计提疑问$q$, $q$Thực hành giải trình nghiệp vụ kế toán nâng cao về trích lập dự phòng nợ xấu và giảm giá hàng tồn kho với kiểm toán viên.$q$, $q$Đoàn kiểm toán độc lập đang kiểm tra báo cáo tài chính cuối năm của công ty. Bạn được giao nhiệm vụ giải trình với trưởng đoàn kiểm toán (Anh Trần) về căn cứ trích lập dự phòng nợ phải thu khó đòi và tình hình phân bổ chi phí trả trước.$q$, ARRAY[$q$Thành thạo thuật ngữ tài chính - kế toán chuyên sâu (坏账准备, 计提依据, 存货跌价准备, 长期待摊费用)$q$,$q$Cung cấp số liệu và lập luận chặt chẽ, chuyên nghiệp theo chuẩn mực kế toán$q$,$q$Tự tin làm việc với các cơ quan kiểm tra, kiểm toán bên ngoài$q$]::text[], $q$advanced$q$, 20, $q$Anh Trần - Trưởng đoàn Kiểm toán độc lập$q$, $q$陈审计 - 外部审计主管$q$, $q$Cực kỳ khắt khe, tỉ mỉ, luôn hỏi sâu vào bản chất số liệu và tính pháp lý.$q$, $q$你好，小阮。关于你们公司年末计提的应收账款坏账准备，我看比例比去年降低了2%，请说明一下具体的计提依据和评估标准。$q$, $q$[{"zh":"陈老师您好，关于坏账准备的计提，我们是严格按照会计准则和账龄分析法执行的。","vi":"Chào thầy Trần, về việc trích lập dự phòng nợ xấu, chúng em thực hiện nghiêm ngặt theo chuẩn mực kế toán và phương pháp phân tích tuổi nợ."},{"zh":"今年我们收回了几笔长期欠款，因此整体坏账风险有所降低。","vi":"Năm nay chúng em đã thu hồi được một số khoản nợ lâu năm, do đó rủi ro nợ xấu tổng thể đã giảm xuống."},{"zh":"这是我们对主要债务人进行的信用评估报告和期后回款凭证。","vi":"Đây là báo cáo đánh giá tín dụng các bên nợ chính và chứng từ tiền về sau kỳ báo cáo."},{"zh":"如果您需要更详细的明细表，我可以在下午整理好发给您。","vi":"Nếu anh cần bảng kê chi tiết hơn, em có thể tổng hợp xong vào chiều nay và gửi anh."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Hỏi đáp quy định chi phí công tác với đồng nghiệp phòng Marketing$q$, $q$差旅费标准咨询$q$, $q$Thực hành giải đáp thắc mắc của đồng nghiệp phòng khác về hạn mức và thủ tục xin tạm ứng chi phí đi công tác.$q$, $q$Bạn là thực tập sinh phòng Kế toán. Đồng nghiệp Trương Vĩ từ phòng Marketing chuẩn bị đi công tác Bắc Kinh và đến gặp bạn để hỏi về hạn mức tiền ở khách sạn, phụ cấp đi lại cũng như thủ tục xin tạm ứng chi phí.$q$, ARRAY[$q$Nắm vững từ vựng cơ bản về chi phí công tác (差旅费, 暂支, 报销标准)$q$,$q$Biết cách giải thích quy định công ty một cách rõ ràng, thân thiện$q$,$q$Rèn luyện khả năng giao tiếp nội bộ cấp độ cơ bản$q$]::text[], $q$beginner$q$, 10, $q$Đồng nghiệp phòng Marketing (Trương Vĩ)$q$, $q$市场部同事张伟$q$, $q$Thân thiện, cởi mở, muốn hỏi rõ chi tiết thủ tục trước khi đi công tác.$q$, $q$你好！我下周要去北京出差三天，想咨询一下住宿和餐饮的报销标准是多少？另外需要怎么申请借款呢？$q$, $q$[{"zh":"出差标准的规定在公司员工手册里有详细说明。","vi":"Quy định về tiêu chuẩn đi công tác có thuyết minh chi tiết trong sổ tay nhân viên."},{"zh":"您 need 先在系统上填写出差申请单和暂支单。","vi":"Anh cần điền đơn xin đi công tác và đơn tạm ứng trên hệ thống trước."},{"zh":"一线城市的住宿标准是每天400元。","vi":"Hạn mức tiền phòng ở các thành phố cấp 1 là 400 tệ một ngày."},{"zh":"回来后请在五天内提交发票办理报销。","vi":"Sau khi về xin vui lòng nộp hóa đơn thanh toán trong vòng 5 ngày."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Nhắc nhở khách hàng doanh nghiệp về khoản thanh toán quá hạn$q$, $q$催收逾期货款$q$, $q$Thực hành gọi điện nhắc nợ đối với đại diện kế toán của công ty khách hàng một cách khéo léo và chuyên nghiệp.$q$, $q$Khoản thanh toán đơn hàng tháng trước của Công ty Tập đoàn Viễn Đông đã quá hạn 10 ngày. Bạn được giao nhiệm vụ gọi điện cho cô Lý - kế toán thanh toán của đối tác để truy thu tiền hàng và xác nhận thời gian chuyển khoản.$q$, ARRAY[$q$Sử dụng thuật ngữ kế toán công nợ (到期应付款, 对账单, 汇款计划)$q$,$q$Rèn luyện kỹ năng nhắc nợ khéo léo, lịch sự nhưng kiên quyết$q$,$q$Xác nhận và ghi nhận cam kết thanh toán của khách hàng$q$]::text[], $q$intermediate$q$, 15, $q$Đại diện kế toán thanh toán khách hàng (Cô Lý)$q$, $q$客户公司财务李会计$q$, $q$Lịch sự nhưng bận rộn, có xu hướng hoãn thanh toán nếu không được hối thúc rõ ràng.$q$, $q$喂，你好！我是远东集团的财务小李，请问有什么事吗？$q$, $q$[{"zh":"我们注意到贵公司有一笔上个月的货款已经逾期了。","vi":"Chúng tôi ghi nhận quý công ty có một khoản tiền hàng tháng trước đã quá hạn."},{"zh":"请问这笔款项目前排在具体的付款计划中了吗？","vi":"Xin hỏi khoản tiền này hiện đã được sắp xếp trong kế hoạch thanh toán cụ thể chưa?"},{"zh":"我重新发一份具体的对账单到您的邮箱，请查收。","vi":"Tôi gửi lại một bản bảng đối chiếu công nợ cụ thể vào email của cô, vui lòng kiểm tra."},{"zh":"希望贵公司能在本周五前完成转账，以免影响后续合作。","vi":"Hy vọng quý công ty có thể hoàn thành chuyển khoản trước thứ Sáu tuần này để không ảnh hưởng hợp tác sau này."}]$q$),
($q$Tài chính - Kế toán$q$, $q$Báo cáo dự báo dòng tiền và đề xuất điều chuyển vốn với Trưởng phòng$q$, $q$汇报现金流预测与资金调拨$q$, $q$Trình bày báo cáo dự báo dòng tiền ngắn hạn và đề xuất phương án điều chuyển tiền giữa các tài khoản ngân hàng với Trưởng phòng Tài chính.$q$, $q$Bạn phát hiện tài khoản thanh toán chính của công ty sắp thiếu hụt tiền mặt để trả lương và thanh toán cho nhà cung cấp tuần tới. Bạn cần làm việc trực tiếp với Trưởng phòng Tài chính (Anh Vương) để báo cáo số liệu và đề xuất rút tiền từ tài khoản tiết kiệm có kỳ hạn.$q$, ARRAY[$q$Trình bày chuyên nghiệp các số liệu dòng tiền (现金流缺口, 定期存款, 划转资金)$q$,$q$Rèn luyện khả năng lập luận, đề xuất giải pháp quản lý thanh khoản$q$,$q$Ứng đáp tự tin trước câu hỏi phản biện của cấp trên$q$]::text[], $q$intermediate$q$, 15, $q$Trưởng phòng Tài chính (Anh Vương)$q$, $q$财务经理王经理$q$, $q$Nghiêm túc, coi trọng số liệu chính xác và tư duy giải quyết vấn đề nhanh gọn.$q$, $q$小张，你找我？针对下周的资金头寸预测，你梳理得怎么样了？$q$, $q$[{"zh":"根据最新的现金流预测，下周我们面临约五十万元的资金缺口。","vi":"Dựa trên dự báo dòng tiền mới nhất, tuần tới chúng ta đối mặt với khoảng 500.000 tệ thiếu hụt quỹ."},{"zh":"主要原因是下周集中有三家供应商的到期款项要支付。","vi":"Nguyên nhân chính là tuần tới tập trung thanh toán khoản đến hạn cho 3 nhà cung cấp."},{"zh":"我建议从招商银行的定期账户调拨一部分资金过来。","vi":"Tôi đề xuất điều chuyển một phần tiền từ tài khoản tiền gửi có kỳ hạn tại ngân hàng Chiêu Thương sang."},{"zh":"这样可以既保证流动性，又能最大程度减少利息损失。","vi":"Làm như vậy vừa đảm bảo tính thanh khoản, vừa giảm thiểu tối đa tổn thất tiền lãi."}]$q$),
